import React from 'react';
import { chakra, useStyleConfig } from '@chakra-ui/react';
import { Link as RouterLink } from 'react-router-dom';
import { isSafeHref, isInternalHref } from 'app/utils/safeHref';
import { useSafeHref } from 'app/hooks/useSafeHref';

type ZimmLinkBaseProps = {
  label: string;
  size?: 'large' | 'small';
};

type ZimmAnchorLinkProps = ZimmLinkBaseProps & {
  href: string;
  onClick?: () => void;
};

type ZimmButtonLinkProps = ZimmLinkBaseProps & {
  href?: never;
  onClick: () => void;
};

/** Props union — href makes it an anchor; omitting href requires onClick (button semantics). */
export type ZimmLinkProps = ZimmAnchorLinkProps | ZimmButtonLinkProps;

const ChakraRouterLink = chakra(RouterLink);

/**
 * Atom — underlined text link rendered in two sizes (Large/Small).
 * Renders as `<button>` when no `href` is given. Otherwise: an internal href (see
 * `isInternalHref`) renders as a client-side-routed `<Link>`, prefixed with the current
 * site/locale via `useSafeHref()`; anything else `isSafeHref` allows (external/tel/mailto/#)
 * renders as a plain `<a>`, unprefixed — see `zimmNavItem/index.tsx`'s own fix for the same
 * class of bug (an unprefixed internal href always falls back to the default site).
 * All visual states live in `zimmLink.css.ts`.
 */
export const ZimmLink = (props: ZimmLinkProps) => {
  const { label, size = 'large', onClick } = props;
  const styles = useStyleConfig('ZimmLink', { size: size === 'small' ? 'sm' : 'lg' });
  const buildHref = useSafeHref();

  if ('href' in props && props.href && isSafeHref(props.href)) {
    const { href } = props;

    if (isInternalHref(href)) {
      return (
        <ChakraRouterLink to={buildHref(href)} onClick={onClick} __css={styles}>
          {label}
        </ChakraRouterLink>
      );
    }

    return (
      <chakra.a href={href} onClick={onClick} __css={styles}>
        {label}
      </chakra.a>
    );
  }

  return (
    <chakra.button type="button" onClick={onClick} __css={styles}>
      {label}
    </chakra.button>
  );
};

import { defineStyleConfig } from '@chakra-ui/react';

const MOTION = 'var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard)';

// All visual states live here. ZimmLink's index.tsx is a thin mapping layer only:
// Zimmermann size prop ('large' | 'small') → Chakra size names ('lg' | 'sm').

export const ZimmLink = defineStyleConfig({
  baseStyle: {
    display: 'inline-flex',
    alignItems: 'center',
    // WCAG 2.2 AA SC 2.5.8 — 24px minimum target. Inline text links are exempt when
    // the line spacing provides a 24px offset, but explicit vertical padding ensures
    // both sizes reliably clear the threshold. Matches Figma's container py: 4px
    // (alias/space/100 = var(--zimm-scale-2xs)).
    paddingBlock: 'var(--zimm-scale-2xs)',
    fontFamily: 'var(--zimm-font-family-body)',
    fontWeight: 'var(--zimm-font-weight-medium)',
    letterSpacing: 'var(--zimm-font-letterspacing-xs)',
    textDecoration: 'underline',
    background: 'transparent',
    border: 'none',
    cursor: 'pointer',
    color: 'var(--zimm-color-link-default)',
    transition: `color ${MOTION}`,
    _hover: {
      color: 'var(--zimm-color-link-hover)',
      textDecoration: 'underline',
    },
    _focusVisible: {
      outline: 'var(--zimm-focus-ring)',
      outlineOffset: 'var(--zimm-focus-ring-offset-default)',
      boxShadow: 'none',
    },
  },
  sizes: {
    // Default/Link-lg: 14px / 500 / 18px lh / uppercase
    lg: {
      fontSize: 'var(--zimm-font-size-2xs)',
      lineHeight: 'var(--zimm-font-lineheight-2xs)',
      textTransform: 'uppercase',
    },
    // Default/Link-sm: 12px / 500 / 14px lh / capitalize
    sm: {
      fontSize: 'var(--zimm-font-size-3xs)',
      lineHeight: 'var(--zimm-font-lineheight-4xs)',
      textTransform: 'capitalize',
    },
  },
  defaultProps: {
    size: 'lg',
  },
});

