import { chromium } from 'playwright';

const url = 'http://localhost:6007/iframe.html?id=commerce-zimmcartitemactions--default&viewMode=story';
const browser = await chromium.launch();
const page = await browser.newPage();
const consoleErrors = [];
page.on('pageerror', (e) => consoleErrors.push(`pageerror: ${e.message}`));
page.on('console', (msg) => { if (msg.type() === 'error') consoleErrors.push(`console.error: ${msg.text()}`); });
await page.goto(url, { waitUntil: 'networkidle' });
await page.waitForTimeout(500);

const result = await page.evaluate(() => {
  const buttons = Array.from(document.querySelectorAll('button'));
  const removeBtn = buttons.find((b) => b.textContent?.trim() === 'Remove');
  const wishlistBtn = buttons.find((b) => b.textContent?.trim() === 'Move to Wishlist');
  const row = removeBtn ? removeBtn.parentElement : null;
  const rowStyle = row ? getComputedStyle(row) : null;
  const removeStyle = removeBtn ? getComputedStyle(removeBtn) : null;
  const removeRect = removeBtn ? removeBtn.getBoundingClientRect() : null;
  const wishlistRect = wishlistBtn ? wishlistBtn.getBoundingClientRect() : null;
  return {
    bodyText: document.body.innerText,
    rowDisplay: rowStyle?.display,
    rowGap: rowStyle?.gap ?? rowStyle?.columnGap,
    removeFontSize: removeStyle?.fontSize,
    removeFontWeight: removeStyle?.fontWeight,
    removeLineHeight: removeStyle?.lineHeight,
    removeTextTransform: removeStyle?.textTransform,
    removeTextDecoration: removeStyle?.textDecorationLine,
    removeColor: removeStyle?.color,
    removePaddingBlock: removeStyle ? `${removeStyle.paddingTop} / ${removeStyle.paddingBottom}` : null,
    removeRectHeight: removeRect?.height,
    gapBetweenButtons: removeRect && wishlistRect ? wishlistRect.left - removeRect.right : null,
  };
});

console.log(JSON.stringify(result, null, 2));
console.log('CONSOLE_ERRORS:', JSON.stringify(consoleErrors));
await browser.close();
EOF
