await page.evaluate(() => (document.activeElement)?.blur());
const btnHandle = await page.$('button');
await btnHandle.hover();
await page.waitForTimeout(100);
const hovered = await page.evaluate(() => {
  const btn = Array.from(document.querySelectorAll('button')).find((b) => b.textContent?.trim() === 'Remove');
  const s = getComputedStyle(btn);
  return { color: s.color, textDecoration: s.textDecorationLine };
});

console.log(JSON.stringify({ before, focused, hovered }, null, 2));
await browser.close();
