import { describe, test, expect, vi, beforeEach } from 'vitest';
import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import { ChakraProvider } from '@chakra-ui/react';
import { IntlProvider } from 'react-intl';
import theme from 'app/theme';
import { ZimmCartItemActions } from './index';
import type { WishlistMoveResult } from './index';
import { ZimmCartItemActions as ZimmCartItemActionsRecipe } from './zimmCartItemActions.css';
import { ZimmLink as ZimmLinkRecipe } from 'app/components/ui-kits/atoms/zimmLink/zimmLink.css';

const { mockNotifyAddedToWishlist, mockNotifyAlreadyInWishlist } = vi.hoisted(() => ({
  mockNotifyAddedToWishlist: vi.fn(),
  mockNotifyAlreadyInWishlist: vi.fn(),
}));

// Smallest-surface mock (testing.md's mocking guidance): this suite is ZimmCartItemActions's own
// contract, not useCartMessages's (already covered by useCartMessages.test.ts) — mocked here so
// no real Chakra toast/portal is involved in these assertions.
vi.mock('app/hooks/useCartMessages', () => ({
  useCartMessages: () => ({
    notifyAddedToWishlist: mockNotifyAddedToWishlist,
    notifyAlreadyInWishlist: mockNotifyAlreadyInWishlist,
    notifyMaxQuantityReached: vi.fn(),
  }),
}));

// ZimmLink calls useSafeHref() unconditionally, which transitively reaches use-multi-site's
// MultiSiteContext — a JSX-in-.js base file Vitest's default transform cannot parse. Same known
// gap, same fix, as zimmLink/index.test.tsx's own identical mock: this suite never exercises an
// href (both links here are onClick-only, button-mode ZimmLinks), so the returned function is
// never actually invoked — it only needs to exist so the real module is never imported.
vi.mock('app/hooks/useSafeHref', () => ({
  useSafeHref: () => (href: string) => href,
}));

const REMOVE_NAME = 'Remove';
const MOVE_TO_WISHLIST_NAME = 'Move to Wishlist';
const PRODUCT_ID = 'product-abc';
const PRODUCT_NAME = 'Cloud 91 Small Clutch';

const success = (): Promise<WishlistMoveResult> => Promise.resolve({ status: 'success' });
