// run: overriding `onMoveToWishlist` in a test still resolved assertions against the default,
// untouched mock, silently passing for the wrong reason.
const renderActions = (props: Partial<React.ComponentProps<typeof ZimmCartItemActions>> = {}) => {
  const onRemove = props.onRemove ?? vi.fn();
  const onMoveToWishlist = props.onMoveToWishlist ?? vi.fn(success);
  const onGuestWishlistClick = props.onGuestWishlistClick ?? vi.fn();
  const utils = render(
    <IntlProvider locale="en">
      <ChakraProvider theme={theme}>
        <ZimmCartItemActions
          productId={PRODUCT_ID}
          productName={PRODUCT_NAME}
          isGuest={false}
          {...props}
          onRemove={onRemove}
          onMoveToWishlist={onMoveToWishlist}
          onGuestWishlistClick={onGuestWishlistClick}
        />
      </ChakraProvider>
    </IntlProvider>,
  );
  return { ...utils, onRemove, onMoveToWishlist, onGuestWishlistClick };
};

describe('ZimmCartItemActions', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe('default rendering (pass criterion 1)', () => {
    test('renders both links as buttons with the exact accessible names', () => {
      renderActions();
      expect(screen.getByRole('button', { name: REMOVE_NAME })).toBeInTheDocument();
      expect(screen.getByRole('button', { name: MOVE_TO_WISHLIST_NAME })).toBeInTheDocument();
    });

    test('the row recipe declares no colour/hover/focus of its own — ZimmLink stays the single, uncontested styling surface for both links', () => {
      // See zimmCartItemActions.css.ts's own docblock: link.default and text.default resolve to
      // the same primitive (grey[900]), so a plain ZimmLink already renders the spec's colour —
      // adding a second, competing declaration here would fight ZimmLink's own recipe instead of
      // composing it (overrideStyling.md's "one canonical styling surface" rule).
      const baseStyle = ZimmCartItemActionsRecipe.baseStyle as Record<string, unknown>;
      expect(baseStyle.color).toBeUndefined();
      expect(baseStyle._hover).toBeUndefined();
      expect(baseStyle._focusVisible).toBeUndefined();
      expect(baseStyle.gap).toBe('var(--zimm-scale-xl)');
    });
  });

  describe('focus-visible is inherited from ZimmLink and genuinely differs from default (pass criterion 2)', () => {
    // jsdom cannot exercise a real :focus-visible pseudo-class match (same disclosed limitation
    // zimmQuantityStepper/index.test.tsx's own "State 5" recipe-level assertions rely on) — this
    // proves the underlying premise directly from ZimmLink's own recipe object (the same one
    // useStyleConfig('ZimmLink', ...) resolves against for both links here) rather than
    // re-testing ZimmLink's own contract, which is zimmLink/index.test.tsx's job, not this file's.
    test('ZimmLink carries a real focus-visible outline with no equivalent default-state outline', () => {
      const large = ZimmLinkRecipe.baseStyle as Record<string, unknown>;
      expect(large.outline).toBeUndefined();
      expect((large._focusVisible as Record<string, unknown>).outline).toBe('var(--zimm-focus-ring)');
    });
  });

  describe('no disabled state exists (pass criterion 3)', () => {
    test('neither link ever carries a disabled/aria-disabled attribute — there is no prop to request one', () => {
      renderActions();
      expect(screen.getByRole('button', { name: REMOVE_NAME })).not.toBeDisabled();
      expect(screen.getByRole('button', { name: REMOVE_NAME })).not.toHaveAttribute('aria-disabled');
      expect(screen.getByRole('button', { name: MOVE_TO_WISHLIST_NAME })).not.toBeDisabled();
      expect(screen.getByRole('button', { name: MOVE_TO_WISHLIST_NAME })).not.toHaveAttribute('aria-disabled');
    });
  });

  describe('Remove (pass criteria 4 & 5 — one call regardless of the line quantity, which this component never receives or loops over)', () => {
    test('clicking Remove calls onRemove exactly once', () => {
      const { onRemove } = renderActions();
      fireEvent.click(screen.getByRole('button', { name: REMOVE_NAME }));
      expect(onRemove).toHaveBeenCalledTimes(1);
    });

    test('clicking Remove twice still only issues two independent single calls — never a loop from one click', () => {
      const { onRemove } = renderActions();
      fireEvent.click(screen.getByRole('button', { name: REMOVE_NAME }));
      fireEvent.click(screen.getByRole('button', { name: REMOVE_NAME }));
      expect(onRemove).toHaveBeenCalledTimes(2);
    });
  });

  describe('authenticated wishlist move — success (pass criterion 6)', () => {
    test('calls onMoveToWishlist, then onRemove, then emits the product-named success message', async () => {
      const { onMoveToWishlist, onRemove } = renderActions({ isGuest: false });

      fireEvent.click(screen.getByRole('button', { name: MOVE_TO_WISHLIST_NAME }));

      await waitFor(() => expect(onRemove).toHaveBeenCalledTimes(1));
      expect(onMoveToWishlist).toHaveBeenCalledTimes(1);
      expect(mockNotifyAddedToWishlist).toHaveBeenCalledWith(PRODUCT_NAME);
      expect(mockNotifyAlreadyInWishlist).not.toHaveBeenCalled();
    });
  });

  describe('authenticated wishlist move — already in wishlist (pass criterion 7)', () => {
    test('emits the warning message and leaves the item in the cart — onRemove is never called', async () => {
      const { onRemove, onMoveToWishlist } = renderActions({
        isGuest: false,
        onMoveToWishlist: vi.fn(alreadyInWishlist),
      });

      fireEvent.click(screen.getByRole('button', { name: MOVE_TO_WISHLIST_NAME }));

      await waitFor(() => expect(onMoveToWishlist).toHaveBeenCalledTimes(1));
      expect(mockNotifyAlreadyInWishlist).toHaveBeenCalledTimes(1);
      expect(mockNotifyAddedToWishlist).not.toHaveBeenCalled();
      expect(onRemove).not.toHaveBeenCalled();
    });
  });

  describe('guest click (pass criterion 8)', () => {
    test('opens the shared auth drawer via onGuestWishlistClick and leaves the item in the cart — the real move never runs', () => {
      const { onGuestWishlistClick, onMoveToWishlist, onRemove } = renderActions({ isGuest: true });

      fireEvent.click(screen.getByRole('button', { name: MOVE_TO_WISHLIST_NAME }));

      expect(onGuestWishlistClick).toHaveBeenCalledTimes(1);
      expect(onMoveToWishlist).not.toHaveBeenCalled();
      expect(onRemove).not.toHaveBeenCalled();
    });
  });

  describe("pending-item resume across auth (pass criterion 9 — React-state half; the session-storage half and the 5-minute bound are usePendingWishlistItem.test.ts's own exhaustive cases, not re-derived here)", () => {
    test('a guest click, followed by the same instance re-rendering as authenticated, resumes the move automatically', async () => {
      const onMoveToWishlist = vi.fn(success);
      const onRemove = vi.fn();
      const onGuestWishlistClick = vi.fn();
      const { rerender } = render(
        <IntlProvider locale="en">
          <ChakraProvider theme={theme}>
            <ZimmCartItemActions
              productId={PRODUCT_ID}
              productName={PRODUCT_NAME}
              isGuest={true}
              onRemove={onRemove}
              onMoveToWishlist={onMoveToWishlist}
              onGuestWishlistClick={onGuestWishlistClick}
            />
          </ChakraProvider>
        </IntlProvider>,
      );

      fireEvent.click(screen.getByRole('button', { name: MOVE_TO_WISHLIST_NAME }));
      expect(onMoveToWishlist).not.toHaveBeenCalled();

      // Same mounted instance transitioning isGuest true -> false — the email-code / create-
      // account shape (the page never unloads), matching usePendingWishlistItem's own doc.
      rerender(
        <IntlProvider locale="en">
          <ChakraProvider theme={theme}>
            <ZimmCartItemActions
              productId={PRODUCT_ID}
              productName={PRODUCT_NAME}
              isGuest={false}
              onRemove={onRemove}
              onMoveToWishlist={onMoveToWishlist}
              onGuestWishlistClick={onGuestWishlistClick}
            />
          </ChakraProvider>
        </IntlProvider>,
      );

      await waitFor(() => expect(onMoveToWishlist).toHaveBeenCalledTimes(1));
      await waitFor(() => expect(onRemove).toHaveBeenCalledTimes(1));
      expect(mockNotifyAddedToWishlist).toHaveBeenCalledWith(PRODUCT_NAME);
    });
  });
});

